// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // The deployer (this contract) is the initial owner.
        // Call owned() as the owner; reference succeeds, buggy reverts.
        vm.prank(address(this));
        c.owned();
        // After the call, the owner should still be this contract
        // (the reference doesn't change it, the buggy reverts so no change).
        assertTrue(c.owner() == address(this));
    }
}

