contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // The deployer is the initial owner; call owned() as the owner
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        // In the reference contract, the call succeeds (ok == true); in the buggy version it reverts (ok == false).
        assertTrue(ok);
    }
}

